effect.shader:
float applyLevels(float value) {
    float range = max(inWhite - inBlack, 0.0001);
    float stretched = clamp((value - inBlack) / range, 0.0, 1.0);
    float shaped = pow(stretched, 1.0 / max(gammaF, 0.01));
    return outBlack + shaped * (outWhite - outBlack);
}

void main() {
    vec4 color = texture(inputImg, acScreenNorm);

    if (channel == 1) {
        color.r = applyLevels(color.r);
    } else if (channel == 2) {
        color.g = applyLevels(color.g);
    } else if (channel == 3) {
        color.b = applyLevels(color.b);
    } else if (channel == 4) {
        color.a = applyLevels(color.a);
    } else {
        color.rgb = vec3(
            applyLevels(color.r),
            applyLevels(color.g),
            applyLevels(color.b)
        );
    }

    fragColor = color;
}
